mapper.select:
select count(1) from kb_space
where lower(space_name) = lower(#{spaceName})
and space_id != #{excludeSpaceId}

select count(1) from kb_page
where space_id = #{spaceId} and parent_id = #{parentId}
  and lower(title) = lower(#{title}) and lifecycle_status != 'TRASH'
and page_id != #{excludePageId}
